/* Full per-character growth transactions. Ordinary combat remains authoritative. */
#ifndef MYRO_CAMPAIGN_PARTY_GROWTH200_H
#define MYRO_CAMPAIGN_PARTY_GROWTH200_H
#include "campaign_follow200.h"
#include "companion_experience200.h"
#include "campaign_rewards_data200.h"
static int party_seed_recruits200(NpcState55*s,unsigned recruits,const Combat*g){unsigned char b[640];if(recruits>=(1u<<19)||party_progress_load200(s,b)<0)return 0;unsigned missing=recruits&~npc_state_u32_55(b+8);if(!missing)return 1;for(unsigned id=0;id<19;id++)if(missing&(1u<<id)){PartyGrowth200 m={(unsigned)(g->level<1?1:g->level>250?250:g->level),0,2,0,partyInitialJobs200[id],0,0};unsigned char stats[6];if(!party_growth_stats200(id,m.job,m.level,stats,&m.hp,&m.sp)||!party_progress_put200(b,id,&m))return 0;}return party_progress_commit200(s,b);}
static int party_promote200(NpcState55*s,unsigned cursor){unsigned char b[640];if(party_progress_load200(s,b)<0)return 0;unsigned mask=npc_state_u32_55(b+8),changed=0;for(unsigned id=0;id<19;id++)if(mask&(1u<<id)){PartyGrowth200 m;party_growth_read200(b+16+id*32,&m);unsigned job=party_growth_promotion200(id,m.job,m.jobLevel,cursor);if(job==m.job)continue;unsigned char stats[6];unsigned hp,sp;if(!party_growth_stats200(id,job,m.level,stats,&hp,&sp))return 0;m.job=job;m.jobLevel=1;m.jobExp=0;m.hp=m.hp?hp:0;m.sp=sp;if(!party_progress_put200(b,id,&m))return 0;changed=1;}return !changed||party_progress_commit200(s,b);}
static void party_growth_apply200(CampaignFollower200*m,const PartyGrowth200*p){int refresh=!m->initialized||m->level!=p->level||m->job!=p->job;m->level=p->level;m->exp=p->exp;m->jobLevel=p->jobLevel;m->jobExp=p->jobExp;m->job=p->job;m->hp=p->hp;m->sp=p->sp;if(refresh)party_growth_stats200(m->id,m->job,m->level,m->stats,&m->maxHP,&m->maxSP);}
static int party_gain_award200(Combat*g,int base,int job,float x,float y,unsigned milestone){if(!campaignPartyState200)return 0;unsigned char b[640];if(party_progress_load200(campaignPartyState200,b)<0)return 0;PartyGrowth200 next[3];unsigned changed=0;for(unsigned i=0;i<campaignParty200.count&&i<3;i++){CampaignFollower200*m=campaignParty200.members+i;if(!m->initialized||!m->hp||m->map!=g->mapId||combat_dist(m->x,m->y,x,y)>192)continue;if(m->id>=19||!(npc_state_u32_55(b+8)&(1u<<m->id)))return 0;party_growth_read200(b+16+m->id*32,next+i);if(!party_growth_gain200(next+i,m->id,base,job,gameRates164[0],gameRates164[1])||!party_progress_put200(b,m->id,next+i))return 0;changed|=1u<<i;}if(milestone){if(milestone>36)return 0;npc_state_put32_55(b+12,milestone);}if(!changed&&!milestone)return 1;if(!party_progress_commit200(campaignPartyState200,b)){combat_message(g,"Companion EXP could not be saved.");return 0;}for(unsigned i=0;i<campaignParty200.count&&i<3;i++)if(changed&(1u<<i))party_growth_apply200(campaignParty200.members+i,next+i);return 1;}
static void party_gain_exp200(Combat*g,const CombatMob*mob){if(mob->training||mob->kind>=MOB_SPEC_COUNT)return;const MobSpec*m=mobSpecs+mob->kind;party_gain_award200(g,m->exp,m->jexp,mob->x,mob->y,0);}
static void campaign_progress_reward200(Combat*g){if(campaign_sandbox_state228(campaignPartyState200))return;Campaign200 story;if(!campaignPartyState200||campaign_load200(campaignPartyState200,&story)!=1)return;unsigned char b[640];if(party_progress_load200(campaignPartyState200,b)<0)return;unsigned last=npc_state_u32_55(b+12);if(last>=story.cursor||last>=36)return;int base=campaignStageRewards200[last],job=base/2;if(!party_gain_award200(g,base,job,g->x,g->y,last+1))return;combat_gain_exp(g,base,job);combat_notice(g,POP_REWARDS,"Story objective complete. Base and job EXP awarded.");}
#endif
